  const originalCanAccess=window.canAccess;
  const originalPageTitleFor=window.pageTitleFor;
  const originalPageContent=window.pageContent;
  const originalRender=window.render;
  window.canAccess=function(page){if(page==='superadmin')return isSA();return originalCanAccess(page);};
  window.pageTitleFor=function(page){if(page==='superadmin')return 'Super Admin Console';return originalPageTitleFor(page);};
  window.pageContent=function(){if(currentPage==='superadmin')return page();return originalPageContent();};
  window.render=function(){originalRender();if(isSA()){injectDesktopNav();injectMobileNav();}};

  function injectDesktopNav(){const sidebar=document.querySelector('.sidebar');if(!sidebar||sidebar.querySelector('.sa-nav-injected'))return;const sys=[...sidebar.querySelectorAll('.group')].find(x=>String(x.textContent||'').trim().toUpperCase()==='SYSTEM');if(!sys)return;const group=document.createElement('div');group.className='group sa-nav-injected';group.textContent='PLATFORM';const btn=document.createElement('button');btn.className='navbtn';btn.innerHTML='<span class="navicon">◆</span><span>Super Admin Console</span>';btn.onclick=()=>nav('superadmin');sys.parentNode.insertBefore(group,sys);sys.parentNode.insertBefore(btn,sys);}
  function injectMobileNav(){const sheet=document.querySelector('.mobile-nav-sheet');if(!sheet||sheet.querySelector('.sa-nav-injected'))return;const groups=[...sheet.querySelectorAll('.mobile-nav-group')];const sys=groups.find(x=>String(x.textContent||'').trim().toUpperCase()==='SYSTEM');if(!sys)return;const g=document.createElement('div');g.className='mobile-nav-group sa-nav-injected';g.textContent='PLATFORM';const btn=document.createElement('button');btn.className='mobile-nav-link';btn.innerHTML='<span class="mnl-icon">◆</span><span class="mnl-label">Super Admin Console</span><span class="mnl-arrow">›</span>';btn.onclick=()=>nav('superadmin');sys.parentNode.insertBefore(g,sys);sys.parentNode.insertBefore(btn,sys);}

  window.loadSuperAdminSnapshot=loadSnapshot;window.loadSuperAdminCompanies=loadCompanies;window.loadSuperAdminUsers=loadUsers;window.refreshSuperAdminAll=refreshAll;window.setSuperAdminTab=setTab;window.runSuperAdminCompanySearch=()=>{state.companiesLoaded=false;loadCompanies();};window.runSuperAdminUserSearch=()=>{state.usersLoaded=false;loadUsers();};window.openSuperAdminCompany=openCompany;window.renderSuperAdminCompanyDetailModal=renderCompanyModal;window.openSuperAdminEditCompany=editCompany;window.saveSuperAdminCompany=saveCompany;window.openSuperAdminCreateCompany=createCompanyModal;window.createSuperAdminCompany=createCompany;window.openSuperAdminCreateSite=createSiteModal;window.createSuperAdminSite=createSite;window.openSuperAdminEditSite=editSite;window.saveSuperAdminSite=saveSite;window.openSuperAdminCreateDepartment=createDeptModal;window.createSuperAdminDepartment=createDept;window.openSuperAdminEditDepartment=editDept;window.saveSuperAdminDepartment=saveDept;window.openSuperAdminEditMembership=editMembership;window.saveSuperAdminMembership=saveMembership;

  ensureStyles();
  setTimeout(()=>{if(typeof render==='function')render();},0);
